"""Generate a fixture-specific publication ablation without editing production.

The all-enabled control and selective arm use the same generated bytecode. Only
the process property differs. The selected production source is never written.
This command creates a fresh output directory and refuses to overwrite one.
"""

from __future__ import annotations

import argparse
import difflib
import hashlib
import json
from pathlib import Path


SOURCE_REL = Path("core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java")
JAVA_REL = Path("org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.java")
EXPECTED_SOURCE_SHA256 = "cb0749719313b85c8cd134b6c03085f712915188f0e53333cbd46e19e2f0f96e"
PROPERTY = "rdf4j.lmdb.resultCoordinates.experiment.omitFactorTargets"


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def replace_once(source: str, before: str, after: str) -> str:
    count = source.count(before)
    if count != 1:
        raise ValueError(f"Expected exactly one source site; found {count}: {before!r}")
    return source.replace(before, after, 1)


def generate(source: str) -> str:
    source = replace_once(
        source,
        "\tfinal byte[] cacheBanks;\n",
        "\tfinal byte[] cacheBanks;\n"
        "\t// Experimental only: identical membership branch and array layout in every timed arm.\n"
        "\tfinal boolean[] omittedFactorTargets;\n",
    )
    source = replace_once(
        source,
        "\t}\n\n\tNativeResultMaterializer open(LmdbQueryMemoryManager.QueryLedger ledger) {\n",
        "\t\tomittedFactorTargets = experimentalOmissions(projection.names, aliases);\n"
        "\t}\n\n"
        "\tprivate static boolean[] experimentalOmissions(String[] names, int[] aliases) {\n"
        "\t\tboolean[] omitted = new boolean[names.length];\n"
        f'\t\tString configured = System.getProperty("{PROPERTY}", "");\n'
        "\t\tif (configured.isEmpty()) {\n"
        "\t\t\treturn omitted;\n"
        "\t\t}\n"
        '\t\tfor (String entry : configured.split(",", -1)) {\n'
        "\t\t\tString name = entry.trim();\n"
        "\t\t\tif (name.isEmpty()) {\n"
        '\t\t\t\tthrow new IllegalArgumentException("Empty experimental factor target");\n'
        "\t\t\t}\n"
        "\t\t\tint target = -1;\n"
        "\t\t\tfor (int candidate = 0; candidate < names.length; candidate++) {\n"
        "\t\t\t\tif (names[candidate].equals(name)) {\n"
        "\t\t\t\t\ttarget = candidate;\n"
        "\t\t\t\t\tbreak;\n"
        "\t\t\t\t}\n"
        "\t\t\t}\n"
        "\t\t\tif (target < 0) {\n"
        '\t\t\t\tthrow new IllegalArgumentException("Unknown experimental factor target: " + name);\n'
        "\t\t\t}\n"
        "\t\t\tif (aliases[target] != target) {\n"
        '\t\t\t\tthrow new IllegalArgumentException("Experimental factor target must be canonical: " + name);\n'
        "\t\t\t}\n"
        "\t\t\tif (omitted[target]) {\n"
        '\t\t\t\tthrow new IllegalArgumentException("Duplicate experimental factor target: " + name);\n'
        "\t\t\t}\n"
        "\t\t\tomitted[target] = true;\n"
        "\t\t}\n"
        "\t\treturn omitted;\n"
        "\t}\n\n"
        "\tNativeResultMaterializer open(LmdbQueryMemoryManager.QueryLedger ledger) {\n",
    )
    source = replace_once(
        source,
        "\tprivate void rememberFactor(int target, long id, long rowSequence) {\n",
        "\tprivate void rememberFactor(int target, long id, long rowSequence) {\n"
        "\t\tif (plan.omittedFactorTargets[plan.aliases[target]]) {\n"
        "\t\t\treturn;\n"
        "\t\t}\n",
    )
    return source


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    args = parser.parse_args()
    original_bytes = args.source.read_bytes()
    if digest(original_bytes) != EXPECTED_SOURCE_SHA256:
        raise ValueError("Input is not the frozen selected original materializer source")
    original = original_bytes.decode("utf-8")
    generated = generate(original)
    # Only plan configuration and the optional publication entry are changed.
    guard = "\t\tif (plan.omittedFactorTargets[plan.aliases[target]]) {\n\t\t\treturn;\n\t\t}\n"
    body_marker = "/**\n * Evaluation-local last-value memo."
    original_body = original[original.index(body_marker):]
    generated_body = generated[generated.index(body_marker):]
    assert generated_body.replace(guard, "", 1) == original_body
    args.out.mkdir(parents=True, exist_ok=False)
    java = args.out / "src" / JAVA_REL
    java.parent.mkdir(parents=True)
    java.write_text(generated)
    patch = "".join(difflib.unified_diff(
        original.splitlines(keepends=True), generated.splitlines(keepends=True),
        fromfile="a/" + SOURCE_REL.as_posix(), tofile="b/" + SOURCE_REL.as_posix(),
    ))
    (args.out / "publication-overlay.patch").write_text(patch)
    receipt = {
        "format": 1,
        "purpose": "Experimental target publication omission; no production selection",
        "property": PROPERTY,
        "source": str(args.source.resolve()),
        "sourceSha256": digest(original_bytes),
        "generatedSource": str(java.resolve()),
        "generatedSourceSha256": digest(generated.encode()),
        "patchSha256": digest(patch.encode()),
        "unchangedMaterializerBodyExceptEntryGuard": True,
        "selection": "Canonical target names; every requested alias tests its canonical bank",
        "default": "No targets omitted; array and membership check remain present",
        "rejectedConfiguration": ["unknown name", "duplicate name", "empty list entry", "noncanonical alias name"],
        "ordinaryReuseUnchanged": True,
        "factorLookupUnchanged": True,
        "coordinateTransportUnchanged": True,
        "ownershipAndCleanupUnchanged": True,
        "productionSourceWritten": False,
    }
    (args.out / "source-receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")
    print(json.dumps({"source": str(java), "sourceSha256": receipt["generatedSourceSha256"]}))


if __name__ == "__main__":
    main()
